country_event = { # xenophile 1
	id = paragon.40100
	title = "paragon.40100.name"
	desc = "paragon.40100.desc"
	show_sound = par_portrait_12
	is_triggered_only = yes

	picture = GFX_leader_recruitment_bg_renowned
