			name = "LYSANDER_FLEET_NAME"
			effect = {
				set_owner = prev
				create_ship = {
					design = NAME_Reaver
					graphical_culture = "pirate_01"
					name = NAME_First_Pillager
					prefix = no
				}
				create_ship = {
					design = NAME_Dagger
